class Solution {
public:
    vector<int> numberOfPairs(vector<int>& nums) {
        int freq[101] = {0};
        for (int x : nums) {
            freq[x]++;
        }
        int pairs = 0;
        int leftover = 0;
        for (int i = 0; i <= 100; i++) {
            pairs += freq[i] / 2;
            leftover += freq[i] % 2;
        }
        return {pairs, leftover};
    }
};
